def grade(score):
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'

def unit(nbytes):
    if nbytes < 1024:
        return 'B'
    elif nbytes < 1048576:
        return 'KB'

def bucket(age):
    if age < 13:
        return 'child'
    elif age < 20:
        return 'teen'

def speed_label(kmh):
    if kmh < 30:
        label = 'slow'
    elif kmh < 90:
        label = 'normal'
    return label

def plural(count):
    if count == 0:
        return 'none'
    elif count == 1:
        return 'one'

def wind(knots):
    if knots < 4:
        return 'calm'
    elif knots < 11:
        return 'breeze'
    elif knots < 28:
        return 'wind'

def tier(points):
    if points > 500:
        return 'gold'
    elif points > 100:
        return 'silver'

def battery(level):
    if level > 80:
        icon = 'full'
    elif level > 20:
        icon = 'half'
    return icon
